data.pageSchema:
{
  "renderer": "page",
  "body": [
    {
      "renderer": "form",
      "controls": [
        {
          "renderer": "input",
          "name": "name",
          "placeholder": "角色名",
          "type": "text",
          "rules": []
        },
        {
          "renderer": "input",
          "name": "description",
          "placeholder": "描述",
          "type": "text",
          "rules": []
        },
        {
          "renderer": "action",
          "text": "搜索",
          "actionType": "submit",
          "body": {}
        }
      ],
      "submitType": "target",
      "inline": true,
      "target": "TolesTable"
    },
    {
      "renderer": "table",
      "name": "TolesTable",
      "maxHeight": 570,
      "showExport": true,
      "initApi": {
        "url": "/api/roles?type=table",
        "method": "get",
        "params": {
          "name": "${name}",
          "description": "${description}"
        }
      },
      "initData": {
        "name": ""
      },
      "columns": [
        {
          "name": "id",
          "label": "ID",
          "visibleOn": "",
          "body": []
        },
        {
          "name": "name",
          "label": "名称",
          "visibleOn": "",
          "body": []
        },
        {
          "name": "description",
          "label": "描述",
          "body": []
        },
        {
          "name": "createdBy",
          "label": "创建人",
          "body": []
        },
        {
          "name": "createdAt",
          "label": "创建时间",
          "body": []
        },
        {
          "name": "updatedAt",
          "label": "更新时间",
          "body": []
        },
        {
          "label": "操作",
          "width": "-",
          "sortable": false,
          "fixed": false,
          "type": "-",
          "align": "none",
          "body": [
            {
              "renderer": "action",
              "category": "icon",
              "icon": "Edit",
              "actionType": "dialog",
              "body": {
                "body": [
                  {
                    "renderer": "form",
                    "controls": [
                      {
                        "renderer": "list",
                        "initApi": {
                          "url": "/api/permissions?type=list",
                          "method": "get",
                          "cached": false,
                          "params": {}
                        },
                        "name": "permissions",
                        "label": "权限",
                        "options": [],
                        "rules": [],
                        "body": [
                          {
                            "renderer": "html",
                            "html": "<div class=\"role_list_text\">${data.description}</div>",
                            "inline": true
                          }
                        ],
                        "optionConfig": {
                          "value": "id",
                          "text": "description"
                        }
                      }
                    ],
                    "name": "UpdateForm",
                    "actionApi": {
                      "url": "/api/role",
                      "method": "put",
                      "params": {
                        "*": "*"
                      }
                    },
                    "reload": "TolesTable",
                    "classname": "roles_update_form"
                  }
                ],
                "footer": [
                  {
                    "renderer": "action",
                    "text": "提交",
                    "actionType": "trigger",
                    "triggered": "UpdateForm",
                    "body": {}
                  }
                ],
                "renderer": "dialog",
                "title": "${data.name}",
                "fullscreen": false,
                "center": false,
                "closeOnClickModal": true,
                "closeOnPressEscape": true,
                "width": 52
              }
            }
          ]
        }
      ],
      "actions": [
        {
          "renderer": "action",
          "text": "添加角色",
          "size": "small",
          "actionType": "dialog",
          "body": {
            "body": [
              {
                "renderer": "form",
                "controls": [
                  {
                    "renderer": "input",
                    "name": "name",
                    "label": "名称",
                    "requiredOn": "1",
                    "placeholder": "请输入",
                    "type": "text",
                    "rules": []
                  },
                  {
                    "renderer": "input",
                    "name": "description",
                    "label": "描述",
                    "requiredOn": "1",
                    "placeholder": "请输入",
                    "type": "text",
                    "rules": []
                  },
                  {
                    "renderer": "select",
                    "name": "permissions",
                    "label": "权限",
                    "placeholder": "请输入",
                    "multiple": true,
                    "optionConfig": {
                      "text": "description",
                      "value": "id"
                    },
                    "options": [],
                    "rules": [],
                    "initApi": {
                      "url": "/api/permissions?type=list",
                      "method": "get",
                      "cached": false,
                      "params": {}
                    }
                  }
                ],
                "name": "CreateForm",
                "actionApi": {
                  "url": "/api/role",
                  "method": "post",
                  "params": {
                    "*": "*"
                  }
                },
                "reload": "TolesTable"
              }
            ],
            "footer": [
              {
                "renderer": "action",
                "text": "提交",
                "actionType": "trigger",
                "triggered": "CreateForm",
                "body": {}
              }
            ],
            "renderer": "dialog"
          },
          "plain": true,
          "icon": "Plus"
        }
      ],
      "height": 490,
      "showDynamicColumn": true,
      "updateOnRowId": "id"
    }
  ],
  "mergeUrlQuery": true,
  "innerStyle": ".roles_update_form {\n  .i-list__item {\n    width: 200px;\n    text-align: center;\n  }\n}\n.role_list_text {\n  padding: 14px 0;\n}"
}
